ALTER TABLE public.expense_bill_payments ADD COLUMN IF NOT EXISTS currency text, ADD COLUMN IF NOT EXISTS original_amount numeric, ADD COLUMN IF NOT EXISTS fx_rate numeric, ADD COLUMN IF NOT EXISTS cash_base_amount numeric, ADD COLUMN IF NOT EXISTS fx_gain_loss numeric;
ALTER TABLE public.payments ADD COLUMN IF NOT EXISTS currency text, ADD COLUMN IF NOT EXISTS original_amount numeric, ADD COLUMN IF NOT EXISTS fx_rate numeric, ADD COLUMN IF NOT EXISTS cash_base_amount numeric, ADD COLUMN IF NOT EXISTS fx_gain_loss numeric;
CREATE OR REPLACE FUNCTION public.finance_fx_account(t uuid,realised boolean) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ident uuid;code_value text:=CASE WHEN realised THEN 'FX-R' ELSE 'FX-U' END;BEGIN IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;SELECT id INTO ident FROM chart_of_accounts WHERE tenant_id=t AND code=code_value;IF ident IS NULL THEN INSERT INTO chart_of_accounts(tenant_id,code,name,account_type,normal_side,sort_order,description) VALUES(t,code_value,'FX gains/losses · '||CASE WHEN realised THEN 'realised' ELSE 'unrealised' END,'other_expense','debit',9900, 'Foreign exchange below operating costs; signed losses and gains') RETURNING id INTO ident;END IF;RETURN ident;END $$;
REVOKE ALL ON FUNCTION public.finance_fx_account(uuid,boolean) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_fx_account(uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.finance_fx_payment_source(t uuid,src text,ident uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT user_has_tenant(auth.uid(),t) THEN RAISE EXCEPTION 'Tenant access required';END IF;IF src='bill' THEN RETURN (SELECT to_jsonb(b) FROM expense_bills b WHERE tenant_id=t AND id=ident);ELSIF src='invoice' THEN RETURN (SELECT to_jsonb(i) FROM invoices i WHERE tenant_id=t AND id=ident);END IF;RAISE EXCEPTION 'Unsupported payment source';END $$;
REVOKE ALL ON FUNCTION public.finance_fx_payment_source(uuid,text,uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_fx_payment_source(uuid,text,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.finance_fx_payment_prepare(t uuid,src text,ident uuid,d date,original numeric,paid_rate numeric,bank uuid,ref text DEFAULT '') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s jsonb;b text;booked numeric;cash numeric;loss numeric;outstanding numeric;ap uuid;gl uuid;fx uuid;q uuid;bs jsonb;ls jsonb;BEGIN
IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;PERFORM finance_assert_open(t,d);PERFORM pg_advisory_xact_lock(hashtextextended('fx:'||t::text,0));s:=finance_fx_payment_source(t,src,ident);SELECT coalesce(base_currency,'HKD') INTO b FROM tenants WHERE id=t;
IF s IS NULL OR coalesce(s->>'currency',b)=b OR coalesce((s->>'fx_rate')::numeric,0)<=0 OR original<=0 OR paid_rate<=0 OR d<coalesce(s->>'bill_date',s->>'invoice_date')::date THEN RAISE EXCEPTION 'Booked foreign source and positive payment amount/rate required';END IF;
IF src='bill' AND s->>'approval_status'<>'posted' OR src='invoice' AND s->>'review_status'<>'Approved' THEN RAISE EXCEPTION 'Approve/book source first';END IF;
IF NOT EXISTS(SELECT 1 FROM journal_entries WHERE tenant_id=t AND status='posted' AND (id::text=s->>'journal_entry_id' OR source_type=src AND source_id=ident::text)) THEN RAISE EXCEPTION 'Source must be posted first';END IF;
booked:=round(original*(s->>'fx_rate')::numeric,2);cash:=round(original*paid_rate,2);loss:=cash-booked;outstanding:=(s->>'total_amount')::numeric-coalesce((s->>'paid_amount')::numeric,(s->>'amount_paid')::numeric,0)-coalesce((s->>'held_amount')::numeric,0);IF booked>outstanding OR booked<=0 THEN RAISE EXCEPTION 'Payment exceeds the remaining balance';END IF;
SELECT to_jsonb(a),a.linked_gl_account_id INTO bs,gl FROM bank_accounts a WHERE tenant_id=t AND id=bank AND is_active;IF gl IS NULL THEN RAISE EXCEPTION 'Select a bank account linked to books';END IF;
SELECT account_id INTO ap FROM account_mapping_rules WHERE tenant_id=t AND rule_type='accounts_payable' LIMIT 1;IF ap IS NULL THEN SELECT id INTO ap FROM chart_of_accounts WHERE tenant_id=t AND code='2000' AND is_active;END IF;IF ap IS NULL THEN RAISE EXCEPTION 'Accounts payable mapping required';END IF;fx:=finance_fx_account(t,true);
ls:=jsonb_build_array(jsonb_build_object('account_id',ap,'debit',booked,'credit',0),jsonb_build_object('account_id',gl,'debit',0,'credit',cash));IF loss<>0 THEN ls:=ls||jsonb_build_array(jsonb_build_object('account_id',fx,'debit',greatest(loss,0),'credit',greatest(-loss,0)));END IF;
IF EXISTS(SELECT 1 FROM finance_entry_drafts WHERE tenant_id=t AND status='waiting' AND source_data->>'fx_source_id'=ident::text) THEN RAISE EXCEPTION 'A payment draft already waits for this source';END IF;
INSERT INTO finance_entry_drafts(tenant_id,kind,label,entry_date,reason,lines,source_data,source_key,status) VALUES(t,'fx_payment','Foreign payment · '||coalesce(s->>'vendor_name',s->>'invoice_number','Invoice'),d,'Payment at '||paid_rate||'; realised FX '||loss,ls,jsonb_build_object('fx_source',src,'fx_source_id',ident,'source_fingerprint',md5(s::text),'bank',bank,'bank_fingerprint',md5(bs::text),'original',original,'currency',s->>'currency','paid_rate',paid_rate,'booked',booked,'cash',cash,'loss',loss,'reference',ref), 'fx-payment:'||ident||':'||gen_random_uuid(),'waiting') RETURNING id INTO q;RETURN q;END $$;
REVOKE ALL ON FUNCTION public.finance_fx_payment_prepare(uuid,text,uuid,date,numeric,numeric,uuid,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_fx_payment_prepare(uuid,text,uuid,date,numeric,numeric,uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.finance_fx_revaluation_preview(t uuid,m date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE ending date:=(date_trunc('month',m)+interval '1 month -1 day')::date;b text;x record;r record;original numeric;carrying numeric;bal numeric;has_ledger boolean;rows jsonb:='[]';acct uuid;BEGIN
IF NOT user_has_tenant(auth.uid(),t) THEN RAISE EXCEPTION 'Tenant access required';END IF;SELECT coalesce(base_currency,'HKD') INTO b FROM tenants WHERE id=t;
FOR x IN SELECT a.* FROM bank_accounts a WHERE tenant_id=t AND is_active AND currency<>b AND opening_date<=ending ORDER BY id LOOP
SELECT x.opening_balance+coalesce(sum(money_in-money_out),0) INTO original FROM bank_transactions WHERE tenant_id=t AND bank_account_id=x.id AND txn_date<=ending;
SELECT coalesce(sum(l.debit-l.credit),0),count(*)>0 INTO carrying,has_ledger FROM journal_lines l JOIN journal_entries e ON e.id=l.entry_id WHERE l.tenant_id=t AND e.tenant_id=t AND e.status='posted' AND e.entry_date<=ending AND l.account_id=x.linked_gl_account_id;
SELECT * INTO r FROM fx_rate(t,ending,x.currency);bal:=CASE WHEN r.rate IS NOT NULL THEN round(original*r.rate,2) ELSE NULL END;
rows:=rows||jsonb_build_array(jsonb_build_object('source','bank','id',x.id,'label',x.account_name,'currency',x.currency,'original',original,'carrying',CASE WHEN has_ledger THEN carrying ELSE NULL END,'was_rate',CASE WHEN original<>0 AND has_ledger THEN carrying/original ELSE NULL END,'rate',r.rate,'rate_date',r.rate_date,'nearest',r.nearest,'base_now',bal,'movement',CASE WHEN has_ledger THEN bal-carrying ELSE NULL END,'loss',CASE WHEN has_ledger THEN carrying-bal ELSE NULL END,'account_id',x.linked_gl_account_id,'liability',false,'blocked',CASE WHEN x.linked_gl_account_id IS NULL THEN 'Bank account not linked to books' WHEN NOT has_ledger THEN 'Opening balance not recorded in books' WHEN r.rate IS NULL THEN 'Month-end rate missing' ELSE NULL END));END LOOP;
SELECT account_id INTO acct FROM account_mapping_rules WHERE tenant_id=t AND rule_type='accounts_payable' LIMIT 1;IF acct IS NULL THEN SELECT id INTO acct FROM chart_of_accounts WHERE tenant_id=t AND code='2000' AND is_active;END IF;
FOR x IN SELECT 'bill'::text src,id,coalesce(vendor_name,bill_number,'Bill') label,currency,fx_rate,original_total,total_amount,bill_date d FROM expense_bills WHERE tenant_id=t AND approval_status='posted' AND bill_date<=ending AND currency<>b AND original_total IS NOT NULL
UNION ALL SELECT 'invoice',id,invoice_number,currency,fx_rate,original_total,total_amount,invoice_date FROM invoices WHERE tenant_id=t AND invoice_date<=ending AND currency<>b AND original_total IS NOT NULL AND EXISTS(SELECT 1 FROM journal_entries WHERE tenant_id=t AND source_type='invoice' AND source_id=invoices.id::text AND status='posted' AND entry_date<=ending) ORDER BY id LOOP
IF x.src='bill' THEN SELECT x.total_amount-coalesce(sum(amount),0) INTO carrying FROM expense_bill_payments WHERE tenant_id=t AND bill_id=x.id AND payment_date<=ending AND journal_entry_id IS NOT NULL;ELSE SELECT x.total_amount-coalesce(sum(a.amount_allocated+coalesce(a.credit_note_amount_applied,0)),0) INTO carrying FROM payment_allocations a JOIN payments p ON p.id=a.payment_id WHERE a.tenant_id=t AND a.invoice_id=x.id AND p.payment_date<=ending AND p.journal_entry_id IS NOT NULL;END IF;
IF carrying<=0 THEN CONTINUE;END IF;original:=carrying/nullif(x.fx_rate,0);SELECT * INTO r FROM fx_rate(t,ending,x.currency);bal:=round(original*r.rate,2);
rows:=rows||jsonb_build_array(jsonb_build_object('source',x.src,'id',x.id,'label',x.label,'currency',x.currency,'original',original,'carrying',carrying,'was_rate',x.fx_rate,'rate',r.rate,'rate_date',r.rate_date,'nearest',r.nearest,'base_now',bal,'movement',bal-carrying,'loss',bal-carrying,'account_id',acct,'liability',true,'blocked',CASE WHEN acct IS NULL THEN 'Accounts payable not mapped' WHEN r.rate IS NULL OR x.fx_rate IS NULL THEN 'Rate missing' ELSE NULL END));END LOOP;
FOR x IN SELECT * FROM deposit_opening_balances WHERE tenant_id=t AND as_of_date<=ending AND currency<>b AND original_total IS NOT NULL LOOP SELECT * INTO r FROM fx_rate(t,ending,x.currency);SELECT id INTO acct FROM chart_of_accounts WHERE tenant_id=t AND code='1350' AND is_active;bal:=round(x.original_total*r.rate,2);rows:=rows||jsonb_build_array(jsonb_build_object('source','deposit','id',x.id,'label',x.description,'currency',x.currency,'original',x.original_total,'carrying',x.total_value,'was_rate',x.fx_rate,'rate',r.rate,'rate_date',r.rate_date,'base_now',bal,'movement',bal-x.total_value,'loss',x.total_value-bal,'account_id',acct,'liability',false,'blocked','Deposit returns must be reconciled before revaluation'));END LOOP;
RETURN jsonb_build_object('date',ending,'base',b,'rows',rows);END $$;
REVOKE ALL ON FUNCTION public.finance_fx_revaluation_preview(uuid,date) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_fx_revaluation_preview(uuid,date) TO authenticated;
CREATE OR REPLACE FUNCTION public.finance_fx_revaluation_prepare(t uuid,m date) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s jsonb;x jsonb;ls jsonb:='[]';fx uuid;q uuid;movement numeric;loss numeric:=0;ending date:=(date_trunc('month',m)+interval '1 month -1 day')::date;BEGIN
IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;IF ending>=current_date THEN RAISE EXCEPTION 'Prepare only a completed month';END IF;PERFORM finance_assert_open(t,ending);PERFORM pg_advisory_xact_lock(hashtextextended('fx:'||t::text,0));s:=finance_fx_revaluation_preview(t,m);IF jsonb_array_length(s->'rows')=0 THEN RETURN NULL;END IF;IF EXISTS(SELECT 1 FROM jsonb_array_elements(s->'rows') v WHERE nullif(v->>'blocked','') IS NOT NULL) THEN RAISE EXCEPTION 'Resolve missing carrying amounts, rates or deposit reconciliation first';END IF;
IF EXISTS(SELECT 1 FROM finance_entry_drafts WHERE tenant_id=t AND kind='fx_revaluation' AND entry_date=ending AND status<>'cancelled') THEN RAISE EXCEPTION 'Revaluation already prepared for this month';END IF;fx:=finance_fx_account(t,false);
FOR x IN SELECT * FROM jsonb_array_elements(s->'rows') LOOP movement:=(x->>'movement')::numeric;loss:=loss+(x->>'loss')::numeric;IF movement=0 THEN CONTINUE;END IF;IF (x->>'liability')::boolean THEN movement:=-movement;END IF;ls:=ls||jsonb_build_array(jsonb_build_object('account_id',x->>'account_id','debit',greatest(movement,0),'credit',greatest(-movement,0)));END LOOP;
IF jsonb_array_length(ls)=0 THEN RETURN NULL;END IF;IF loss<>0 THEN ls:=ls||jsonb_build_array(jsonb_build_object('account_id',fx,'debit',greatest(loss,0),'credit',greatest(-loss,0)));END IF;
INSERT INTO finance_entry_drafts(tenant_id,kind,label,entry_date,reason,lines,source_data,source_key,status) VALUES(t,'fx_revaluation','Foreign currency · month-end revaluation',ending,'Month-end rates; reverse on the first of next month',ls,jsonb_build_object('fx_snapshot',s,'fingerprint',md5(s::text)), 'fx-revaluation:'||ending||':'||gen_random_uuid(),'waiting') RETURNING id INTO q;RETURN q;END $$;
REVOKE ALL ON FUNCTION public.finance_fx_revaluation_prepare(uuid,date) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_fx_revaluation_prepare(uuid,date) TO authenticated;
CREATE OR REPLACE FUNCTION public.finance_fx_draft_check(t uuid,q public.finance_entry_drafts) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s jsonb;b jsonb;BEGIN
IF q.kind='fx_revaluation' THEN IF md5(finance_fx_revaluation_preview(t,q.entry_date)::text) IS DISTINCT FROM q.source_data->>'fingerprint' THEN RAISE EXCEPTION 'Foreign balances or rates changed; cancel and prepare again';END IF;PERFORM finance_assert_open(t,(date_trunc('month',q.entry_date)+interval '1 month')::date);
ELSIF q.kind='fx_payment' THEN s:=finance_fx_payment_source(t,q.source_data->>'fx_source',(q.source_data->>'fx_source_id')::uuid);SELECT to_jsonb(a) INTO b FROM bank_accounts a WHERE tenant_id=t AND id=(q.source_data->>'bank')::uuid;IF md5(s::text) IS DISTINCT FROM q.source_data->>'source_fingerprint' OR md5(b::text) IS DISTINCT FROM q.source_data->>'bank_fingerprint' THEN RAISE EXCEPTION 'Payment source changed; prepare again';END IF;END IF;END $$;
REVOKE ALL ON FUNCTION public.finance_fx_draft_check(uuid,public.finance_entry_drafts) FROM PUBLIC,anon;
CREATE OR REPLACE FUNCTION public.finance_fx_draft_finish(t uuid,q public.finance_entry_drafts,j uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s jsonb;r uuid;l record;n int:=0;pid uuid;uid uuid:=auth.uid();BEGIN
IF q.kind='fx_revaluation' THEN INSERT INTO journal_entries(tenant_id,entry_date,memo,source_type,source_id,status,created_by) VALUES(t,(date_trunc('month',q.entry_date)+interval '1 month')::date,'Reverse month-end foreign revaluation','adjustment',q.id::text,'draft',uid) RETURNING id INTO r;
FOR l IN SELECT * FROM journal_lines WHERE tenant_id=t AND entry_id=j ORDER BY line_no LOOP n:=n+1;INSERT INTO journal_lines(tenant_id,entry_id,account_id,debit,credit,line_no,memo,venue) VALUES(t,r,l.account_id,l.credit,l.debit,n,'Automatic reversal of approved revaluation',l.venue);END LOOP;UPDATE journal_entries SET status='posted',posted_at=now() WHERE tenant_id=t AND id=r AND status='draft';UPDATE finance_entry_drafts SET source_data=source_data||jsonb_build_object('reversal_entry_id',r) WHERE tenant_id=t AND id=q.id;
ELSIF q.kind='fx_payment' THEN s:=finance_fx_payment_source(t,q.source_data->>'fx_source',(q.source_data->>'fx_source_id')::uuid);
IF q.source_data->>'fx_source'='bill' THEN INSERT INTO expense_bill_payments(tenant_id,bill_id,payment_date,amount,payment_method,bank_account_id,reference,journal_entry_id,created_by,currency,original_amount,fx_rate,cash_base_amount,fx_gain_loss) VALUES(t,(s->>'id')::uuid,q.entry_date,(q.source_data->>'booked')::numeric,'bank_transfer',(q.source_data->>'bank')::uuid,q.source_data->>'reference',j,uid,q.source_data->>'currency',(q.source_data->>'original')::numeric,(q.source_data->>'paid_rate')::numeric,(q.source_data->>'cash')::numeric,(q.source_data->>'loss')::numeric);UPDATE expense_bills SET paid_amount=paid_amount+(q.source_data->>'booked')::numeric,payment_status=CASE WHEN paid_amount+(q.source_data->>'booked')::numeric>=total_amount THEN 'paid' ELSE 'partial' END WHERE tenant_id=t AND id=(s->>'id')::uuid;
ELSE INSERT INTO payments(tenant_id,supplier_id,payment_date,amount,payment_method,paid_from_account_id,reference_number,journal_entry_id,created_by,currency,original_amount,fx_rate,cash_base_amount,fx_gain_loss) VALUES(t,(s->>'supplier_id')::uuid,q.entry_date,(q.source_data->>'booked')::numeric,'Bank Transfer',(q.source_data->>'bank')::uuid,q.source_data->>'reference',j,uid,q.source_data->>'currency',(q.source_data->>'original')::numeric,(q.source_data->>'paid_rate')::numeric,(q.source_data->>'cash')::numeric,(q.source_data->>'loss')::numeric) RETURNING id INTO pid;INSERT INTO payment_allocations(tenant_id,payment_id,invoice_id,amount_allocated) VALUES(t,pid,(s->>'id')::uuid,(q.source_data->>'booked')::numeric);END IF;END IF;END $$;
REVOKE ALL ON FUNCTION public.finance_fx_draft_finish(uuid,public.finance_entry_drafts,uuid) FROM PUBLIC,anon;
DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.finance_schedule_approve(uuid,uuid,date)'::regprocedure) INTO def;IF position('INSERT INTO journal_entries(tenant_id,entry_date' IN def)=0 OR position('RETURN j;END' IN def)=0 THEN RAISE EXCEPTION 'Selected approval anchor changed';END IF;def:=replace(def,' INSERT INTO journal_entries(tenant_id,entry_date',' PERFORM public.finance_fx_draft_check(t,q); INSERT INTO journal_entries(tenant_id,entry_date');def:=replace(def,'RETURN j;END','PERFORM public.finance_fx_draft_finish(t,q,j);RETURN j;END');EXECUTE def;END $$;